const state = options.getState();
const selectedRowId = state.grid.selectedRows[0];
const item = options.rows.get(selectedRowId);
const { itemType, commandFactory } = options;
const commandOptions = { item, itemType };
const commandAlias = target['command_alias@keyed_name'];
const openItemCommand = commandFactory(commandAlias, commandOptions);
openItemCommand.execute();
